/bin/bash -lc "cat > config/os_test.go <<'EOF'
package config

import (
 \"testing\"
 \"time\"
)

func TestEOLLookupAndBoundaries(t *testing.T) {
 e, found := GetEOL(Ubuntu, \"14.04\")
 if "'!found || e.StandardSupportUntil.Format("2006-01-02") != "2019-04-30" || e.ExtendedSupportUntil.Format("2006-01-02") != "2024-04-30" { t.Fatalf("unexpected EOL: %+v, %v", e, found) }
 if e.IsStandardSupportEnded(e.StandardSupportUntil) || !e.IsStandardSupportEnded(e.StandardSupportUntil.Add(time.Nanosecond)) { t.Fatal("standard support boundary") }
 if e.IsExtendedSuppportEnded(e.ExtendedSupportUntil) || !e.IsExtendedSuppportEnded(e.ExtendedSupportUntil.Add(time.Nanosecond)) { t.Fatal("extended support boundary") }
 if _, found := GetEOL(Ubuntu, "12.10"); found { t.Fatal("unlisted release found") }
}
EOF
GOPROXY=off go test ./config -run TestEOLLookupAndBoundaries -count=1'

